<?php
namespace App\Console\Commands;use App\Services\Hr\HrReportAccessService;use App\Services\Hr\HrReportRunService;use Carbon\CarbonImmutable;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;
class ProcessHrReportSchedules extends Command{
protected$signature='hr:process-report-schedules {--commit}';protected$description='Preview or queue due approved HR report schedules';
public function handle(HrReportRunService$runs,HrReportAccessService$access):int{if(!config('hr.features.engagement_analytics',false)||!config('hr.system_user_id')||!Schema::hasTable('hr_report_schedules')){$this->warn('HR reporting is disabled, unconfigured, or not migrated.');return self::SUCCESS;}$commit=(bool)$this->option('commit');$count=0;DB::table('hr_report_schedules')->where('status','approved')->where('next_due_at','<=',now())->orderBy('next_due_at')->chunkById(100,function($rows)use($runs,$access,$commit,&$count){foreach($rows as$s){$view=DB::table('hr_report_saved_views')->where('id',$s->saved_view_id)->where('company_id',$s->company_id)->where('status','active')->first();$recipients=array_values(array_unique(json_decode($s->recipient_user_ids,true)?:[]));$valid=$view?array_values(array_filter($recipients,fn($userId)=>$access->userAuthorized($userId,$s->company_id,$view->report_kind,true))):[];$checksum=$view?$this->checksum($s,$recipients,$view->view_checksum):null;if(!$view||count($valid)!==count($recipients)||!$checksum||!hash_equals($s->schedule_checksum,$checksum)){if($commit)DB::table('hr_report_schedules')->where('id',$s->id)->update(['status'=>'pending_review','decision_reason'=>'Saved view, schedule checksum, or recipient authorization changed; reapproval is required.','updated_at'=>now()]);continue;}$count++;if(!$commit)continue;$due=CarbonImmutable::parse($s->next_due_at);$key='hr-report:'.$s->id.':'.$due->utc()->format('YmdHis');$run=$runs->queue($view,$s,$due->setTimezone($s->timezone)->toDateString(),$s->format,config('hr.system_user_id'),$key);foreach($valid as$userId)DB::table('hr_report_delivery_events')->insertOrIgnore(['id'=>(string)Str::uuid(),'report_run_id'=>$run->id,'recipient_user_id'=>$userId,'channel'=>$s->delivery_channel,'event_type'=>'queued','idempotency_key'=>'hr-report-delivery:'.$run->id.':'.$userId.':queued','actor_user_id'=>config('hr.system_user_id'),'occurred_at'=>now()]);DB::table('hr_report_schedules')->where('id',$s->id)->update(['last_queued_at'=>now(),'next_due_at'=>$this->next($s,$due),'updated_at'=>now()]);}});$this->info(($commit?'Queued ':'Would queue ').$count.' HR report run(s).');return self::SUCCESS;}
private function checksum(object$s,array$recipients,string$viewChecksum):string{$payload=['saved_view_id'=>$s->saved_view_id,'name'=>$s->name,'cadence'=>$s->cadence,'timezone'=>$s->timezone,'local_time'=>substr($s->local_time,0,5),'day_of_week'=>$s->cadence==='weekly'?(int)$s->day_of_week:null,'day_of_month'=>$s->cadence==='monthly'?(int)$s->day_of_month:null,'format'=>$s->format,'recipient_user_ids'=>$recipients,'delivery_channel'=>$s->delivery_channel,'view_checksum'=>$viewChecksum];return hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));}
private function next(object$s,CarbonImmutable$due):CarbonImmutable{$local=$due->setTimezone($s->timezone);[$hour,$minute]=array_map('intval',explode(':',substr($s->local_time,0,5)));if($s->cadence==='daily')$next=$local->addDay()->setTime($hour,$minute);elseif($s->cadence==='weekly'){$next=$local->addDay();while($next->dayOfWeek!==(int)$s->day_of_week)$next=$next->addDay();$next=$next->setTime($hour,$minute);}else{$next=$local->addMonthNoOverflow()->day(min((int)($s->day_of_month?:1),28))->setTime($hour,$minute);}return$next->utc();}}
